<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api } from '../api/client'
import type { SystemStatus } from '../types/domain'
import Icon from '../components/Icon.vue'
const state = ref<SystemStatus | null>(null), error = ref(''), loading = ref(false)
const labels: Record<string, string> = { database: 'PostgreSQL 数据库', schema: '数据库迁移版本', redis: 'Redis 缓存' }
async function refresh(): Promise<void> { loading.value = true; error.value = ''; try { state.value = await api<SystemStatus>('/system/status') } catch (cause) { error.value = cause instanceof Error ? cause.message : '状态读取失败' } finally { loading.value = false } }
onMounted(refresh)
</script>
<template><div class="page-heading"><div><span class="eyebrow">SYSTEM HEALTH</span><h1>系统状态</h1><p>进程存活、依赖就绪与交易所数据健康分别管理。</p></div><button class="button secondary" :disabled="loading" @click="refresh"><Icon name="refresh" :size="16" />检查状态</button></div><div v-if="error" class="alert error" role="alert">{{ error }}</div><div v-if="loading && !state" class="loading-state">正在检查基础服务…</div><template v-if="state"><div class="system-grid"><article v-for="(value, key) in state.checks" :key="key" class="panel service-card"><span class="service-icon"><Icon :name="key === 'database' ? 'wallet' : key === 'schema' ? 'log' : 'pulse'" :size="24" /></span><h2>{{ labels[key] ?? key }}</h2><span class="pill" :class="value === 'READY' ? 'green-pill' : 'amber-pill'"><span class="status-dot" :class="value === 'READY' ? 'green' : 'amber'"></span>{{ value === 'READY' ? '已就绪' : value === 'MIGRATION_REQUIRED' ? '需要迁移' : '不可用' }}</span><p class="mono muted">{{ value }}</p></article></div><section class="panel"><div class="panel-heading"><h2>运行配置</h2><a v-if="state.app_environment !== 'production'" class="text-link" href="/api/openapi.json" target="_blank" rel="noopener">OpenAPI JSON ↗</a></div><dl class="detail-list"><div><dt>应用版本</dt><dd>{{ state.version }} / {{ state.stage }}</dd></div><div><dt>应用环境</dt><dd class="mono">{{ state.app_environment }}</dd></div><div><dt>交易执行</dt><dd><span class="pill amber-pill"><Icon name="lock" :size="13" />已锁定</span></dd></div><div><dt>交易所接入</dt><dd>等待 E02 实现与验证</dd></div><div><dt>工作空间</dt><dd class="mono">{{ state.workspace_id }}</dd></div></dl></section></template><div class="notice"><Icon name="shield" /><div><strong>服务就绪不等于账户可交易</strong><span>后续还需完成密钥权限、账户模式、实时同步、对账和交易风控验收。</span></div></div></template>
